const trigger = $('Telegram Trigger').first().json;
const message = trigger.message || {};
const audio = message.voice || message.audio || {};
return [
  {
    json: {
      chat_id: String(message.chat?.id || ''),
      user_id: String(message.from?.id || ''),
      file_id: audio.file_id,
      file_size: Number(audio.file_size || 0),
      duration: Number(audio.duration || 0)
    }
  }
];

const text = String($json.text || '').trim();
return [{
  json: {
    text,
    is_valid: text.length >= 5
  }
}];

const message = $json.output?.find?.((item) => item.type === 'message') || $json.output?.[0];
const raw = String(
  message?.content?.find?.((part) => part.type === 'output_text')?.text ||
  message?.content?.[0]?.text ||
  $json.text ||
  ''
).trim();
function stripFences(value) {
  return value.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
}
function parseJson(value) {
  const cleaned = stripFences(value);
  try {
    return JSON.parse(cleaned);
  } catch (error) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) {
      try { return JSON.parse(match[0]); } catch (_) {}
    }
    throw new Error('Model did not return valid calorie JSON');
  }
}
function number(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? Math.round(parsed) : 0;
}
function escapeHtml(value) {
  return String(value || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function progressBar(percent) {
  const filled = Math.max(0, Math.min(10, Math.round(percent / 10)));
  return '▰'.repeat(filled) + '▱'.repeat(10 - filled);
}
const data = parseJson(raw);
const base = $('Code - Normalize Airtable Limit').first().json;
const now = new Date();
const date = String(data.date || now.toISOString().slice(0, 10)).slice(0, 10);
const time = now.toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Moscow' });
const calories = number(data.calories);
const proteins = number(data.proteins);
const fats = number(data.fats);
const carbs = number(data.carbs);
const dailyCalories = Number(base.daily_calories || 0) + calories;
const dailyProteins = Number(base.daily_proteins || 0) + proteins;
const dailyFats = Number(base.daily_fats || 0) + fats;
const dailyCarbs = Number(base.daily_carbs || 0) + carbs;
const dailyMeals = Number(base.daily_meals || 0) + 1;
const goal = Number(base.goal_calories || 2000);
const percent = goal > 0 ? Math.round((dailyCalories / goal) * 100) : 0;
const items = String(data.items || data.items_summary || '').trim();
const rawText = String(data.raw_text || $('Code - Validate Transcription').first().json.text || '').trim();
const telegramText = [
  '🍏 <b>Прием пищи записан!</b>',
  '',
  '📋 <b>Что съедено:</b> ' + escapeHtml(items),
  '🔥 <b>Этот прием:</b> ' + calories + ' ккал',
  '💪 <b>БЖУ:</b> Б: ' + proteins + 'г | Ж: ' + fats + 'г | У: ' + carbs + 'г',
  '',
  '📊 <b>Сегодня:</b>',
  '🥣 Приемов пищи: ' + dailyMeals,
  '🔥 ' + dailyCalories + ' / ' + goal + ' ккал',
  progressBar(percent) + ' ' + percent + '%',
  '💪 Б: ' + dailyProteins + 'г | Ж: ' + dailyFats + 'г | У: ' + dailyCarbs + 'г',
  '',
  base.spreadsheet_url ? '📈 <a href="' + base.spreadsheet_url + '">Открыть дневник питания</a>' : '<i>Данные внесены в личную таблицу.</i>'
].join('\n');
return [
  {
    json: {
      'Дата': date,
      'Время': time,
      'Прием': 'Прием ' + dailyMeals,
      'Исходный текст': rawText,
      'Детализация продуктов': items,
      'Калории (ккал)': calories,
      'Белки (г)': proteins,
      'Жиры (г)': fats,
      'Углеводы (г)': carbs,
      'Итого ккал за день': dailyCalories,
      daily_calories_total: dailyCalories,
      daily_proteins_total: dailyProteins,
      daily_fats_total: dailyFats,
      daily_carbs_total: dailyCarbs,
      daily_meals_total: dailyMeals,
      goal_calories: goal,
      telegram_text: telegramText,
      raw_model_output: raw
    }
  }
];

const found = $('Airtable - Find User').first().json.records?.[0];
const audio = $('Code - Normalize Incoming Audio').first().json;
const record = found || null;
const fields = record?.fields || {};
const dailyRequests = Number(fields.daily_requests || 0);
const status = fields.status || 'free';
const spreadsheetId = String(fields.spreadsheet_id || '').trim();
return [
  {
    json: {
      record_id: record?.id || '',
      telegram_id: String(audio.user_id || ''),
      chat_id: String(audio.chat_id || ''),
      file_id: audio.file_id,
      file_size: Number(audio.file_size || 0),
      duration: Number(audio.duration || 0),
